//  Preferences
//
//  Settings > General > iPhone Storage
//
//  Visual recreation only. Every number, date and app on this screen is static demo
//  data transcribed from a screen recording; nothing here reads real device storage or
//  installed apps. App icons are embedded as base64 PNGs at the bottom of this file.
//

import SwiftUI

// MARK: - Model

struct StorageApp: Identifiable, Hashable {
    let id: String
    let name: String
    let megabytes: Double
    let lastUsed: String?          // dd/MM/yyyy, shown as "Last used: …"
    var version: String? = nil
    var developer: String? = nil
    var appSizeMB: Double? = nil   // when nil, a default split of `megabytes` is used

    var sizeText: String { StorageFormat.size(megabytes) }
    var iconName: String { "StorageIcon_\(id)" }

    var lastUsedDate: Date {
        guard let lastUsed else { return .distantPast }
        return StorageFormat.dateParser.date(from: lastUsed) ?? .distantPast
    }

    var resolvedAppSizeMB: Double { appSizeMB ?? megabytes * 0.45 }
    var documentsMB: Double { max(megabytes - resolvedAppSizeMB, 0) }
}

enum StorageFormat {
    static let dateParser: DateFormatter = {
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_GB_POSIX")
        f.dateFormat = "dd/MM/yyyy"
        return f
    }()

    private static func trimmed(_ value: Double, decimals: Int) -> String {
        var s = String(format: "%.\(decimals)f", value)
        if s.contains(".") {
            while s.hasSuffix("0") { s.removeLast() }
            if s.hasSuffix(".") { s.removeLast() }
        }
        return s
    }

    /// 1000-based like iOS: "20.56 GB", "928.7 MB", "287 KB".
    static func size(_ megabytes: Double) -> String {
        if megabytes >= 1000 { return trimmed(megabytes / 1000, decimals: 2) + " GB" }
        if megabytes >= 1 { return trimmed(megabytes, decimals: 1) + " MB" }
        return trimmed(megabytes * 1000, decimals: 0) + " KB"
    }
}

