// MARK: - Icons

struct StorageIcon: View {
    let name: String
    var size: CGFloat = 35

    var body: some View {
        Image(uiImage: StorageIconStore.image(for: name))
            .resizable()
            .interpolation(.high)
            .aspectRatio(contentMode: .fit)
            .frame(width: size, height: size)
    }
}

/// Decodes the embedded icons (see `StorageIconData` at the bottom of the file) once and caches them.
enum StorageIconStore {
    private static var cache: [String: UIImage] = [:]

    static func image(for name: String) -> UIImage {
        let id = name.replacingOccurrences(of: "StorageIcon_", with: "")
        if let hit = cache[id] { return hit }
        guard let b64 = StorageIconData.png[id],
              let data = Data(base64Encoded: b64),
              let image = UIImage(data: data) else { return UIImage() }
        cache[id] = image
        return image
    }
}

// MARK: - Main screen

private enum StorageSort: String, CaseIterable, Identifiable {
    case size = "Size"
    case name = "Name"
    case lastUsed = "Last Used"
    var id: String { rawValue }
}

struct PhoneStorageView: View {
    @State private var sort: StorageSort = .size
    @State private var showAll = false
    @State private var query = ""

    private var sortedApps: [StorageApp] {
        let apps = StorageDemoData.apps
        switch sort {
        case .size:
            return apps.sorted { $0.megabytes > $1.megabytes }
        case .name:
            return apps.sorted { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }
        case .lastUsed:
            return apps.sorted { $0.lastUsedDate > $1.lastUsedDate }
        }
    }

    private var searchResults: [StorageApp] {
        let q = query.trimmingCharacters(in: .whitespaces)
        return sortedApps.filter { !$0.name.isEmpty && $0.name.localizedCaseInsensitiveContains(q) }
    }

    private var visibleApps: [StorageApp] {
        showAll ? sortedApps : Array(sortedApps.prefix(StorageDemoData.collapsedCount))
    }

    var body: some View {
        List {
            if query.isEmpty {
                Section { StorageUsageCard() }

                recommendationsSection

                Section {
                    HStack {
                        Spacer()
                        Menu {
                            Picker("Sort", selection: $sort) {
                                ForEach(StorageSort.allCases) { Text($0.rawValue).tag($0) }
                            }
                        } label: {
                            HStack(spacing: 4) {
                                Text(sort.rawValue)
                                Image(systemName: "chevron.up.chevron.down")
                                    .font(.caption.weight(.semibold))
                            }
                        }
                    }
                    .listRowBackground(Color.clear)
                    .listRowInsets(EdgeInsets(top: 0, leading: 16, bottom: 0, trailing: 16))
                }

                Section {
                    ForEach(visibleApps) { app in
                        StorageAppRow(app: app)
                    }
                    if !showAll {
                        Button {
                            withAnimation { showAll = true }
                        } label: {
                            Text("Show All").frame(maxWidth: .infinity)
                        }
                    }
                }

                Section {
                    NavigationLink {
                        HiddenAppsView()
                    } label: {
                        HStack(spacing: 12) {
                            StorageIcon(name: "StorageIcon_hiddenapps")
                            Text("Hidden Apps")
                        }
                    }
                }

                Section {
                    StorageSystemRow(iconID: "ios", title: "iOS", sizeText: StorageDemoData.iOSSizeText)
                    StorageSystemRow(iconID: "systemdata", title: "System Data", sizeText: StorageDemoData.systemDataSizeText)
                }
            } else {
                Section {
                    ForEach(searchResults) { app in
                        StorageAppRow(app: app)
                    }
                }
            }
        }
        .listStyle(.insetGrouped)
        .navigationTitle(UIDevice.iPad ? "iPad Storage" : "iPhone Storage")
        .navigationBarTitleDisplayMode(.inline)
        .safeAreaInset(edge: .bottom) { StorageSearchBar(text: $query) }
        .dynamicTypeSize(.xLarge)
        .preferredColorScheme(.dark)
        .scrollDismissesKeyboard(.interactively)
    }

    private var recommendationsSection: some View {
        Group {
            Section {
                StorageRecommendationCard(
                    iconID: "photos",
                    title: "“Recently Deleted” Album",
                    trailing: .text("Empty"),
                    detail: "Save up to 3.52 GB. This will permanently delete all photos and videos kept in the “Recently Deleted” album."
                )
            } header: {
                HStack {
                    Text("Recommendations")
                        .font(.subheadline.weight(.semibold))
                        .foregroundStyle(.secondary)
                    Spacer()
                    Button("Show All") {}
                        .font(.subheadline)
                }
                .textCase(nil)
            }

            Section {
                StorageRecommendationCard(
                    iconID: "photos",
                    title: "Review Your Photos & Videos",
                    trailing: .chevron,
                    detail: "Save up to 1.9 GB. See photos and videos taking up storage in the Photos app and consider deleting them."
                )
            }
        }
    }
}

// MARK: - Pieces

private struct StorageUsageCard: View {
    private struct Segment: Identifiable {
        let id: String
        let gb: Double
        let color: Color
    }

    private let segments: [Segment] = [
        .init(id: "Applications", gb: StorageDemoData.applicationsGB, color: Color(red: 0.93, green: 0.16, blue: 0.27)),
        .init(id: "Photos", gb: StorageDemoData.photosGB, color: Color(red: 0.96, green: 0.54, blue: 0.17)),
        .init(id: "Podcasts", gb: StorageDemoData.podcastsGB, color: Color(red: 1.0, green: 0.80, blue: 0.0)),
        .init(id: "iOS", gb: StorageDemoData.iosGB, color: Color(red: 0.42, green: 0.42, blue: 0.45)),
        .init(id: "System Data", gb: StorageDemoData.systemDataGB, color: Color(red: 0.23, green: 0.23, blue: 0.25)),
    ]

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .firstTextBaseline) {
                Text(UIDevice.iPad ? "iPad" : "iPhone")
                Spacer()
                Text("\(StorageDemoData.usedText) of \(Int(StorageDemoData.totalGB)) GB used")
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }

            GeometryReader { geo in
                HStack(spacing: 1) {
                    ForEach(segments) { seg in
                        Rectangle()
                            .fill(seg.color)
                            .frame(width: max(2, geo.size.width * seg.gb / StorageDemoData.totalGB))
                    }
                    Spacer(minLength: 0)
                }
                .background(Color.black)
                .clipShape(RoundedRectangle(cornerRadius: 4, style: .continuous))
            }
            .frame(height: 22)

            VStack(alignment: .leading, spacing: 8) {
                HStack(spacing: 14) {
                    legend("Applications", segments[0].color)
                    legend("Photos", segments[1].color)
                    legend("Podcasts", segments[2].color)
                    legend("iOS", segments[3].color)
                }
                legend("System Data", segments[4].color)
            }
        }
        .padding(.vertical, 6)
    }

    private func legend(_ title: String, _ color: Color) -> some View {
        HStack(spacing: 6) {
            Circle().fill(color).frame(width: 8, height: 8)
            Text(title).font(.caption)
        }
    }
}

private struct StorageRecommendationCard: View {
    enum Trailing { case text(String), chevron }

    let iconID: String
    let title: String
    let trailing: Trailing
    let detail: String

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(spacing: 12) {
                StorageIcon(name: "StorageIcon_\(iconID)")
                Text(title).font(.subheadline)
                Spacer(minLength: 8)
                switch trailing {
                case .text(let s):
                    Text(s).font(.subheadline).foregroundStyle(.blue)
                case .chevron:
                    Image(systemName: "chevron.right")
                        .font(.footnote.weight(.semibold))
                        .foregroundStyle(.tertiary)
                }
            }
            Text(detail)
                .font(.footnote)
                .foregroundStyle(.secondary)
        }
        .padding(.vertical, 6)
    }
}

private struct StorageAppRow: View {
    let app: StorageApp

    var body: some View {
        NavigationLink {
            StorageAppDetailView(app: app)
        } label: {
            HStack(spacing: 12) {
                StorageIcon(name: app.iconName)
                VStack(alignment: .leading, spacing: 1) {
                    Text(app.name)
                    if let lastUsed = app.lastUsed {
                        Text("Last used: \(lastUsed)")
