}

private struct StorageSearchBar: View {
    @Binding var text: String

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: "magnifyingglass")
                .foregroundStyle(.secondary)
            TextField("Applications", text: $text)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
            if !text.isEmpty {
                Button { text = "" } label: {
                    Image(systemName: "xmark.circle.fill").foregroundStyle(.secondary)
                }
                .buttonStyle(.plain)
            }
        }
        .padding(.horizontal, 16)
        .frame(height: 50)
        .modifier(StorageGlassCapsule())
        .padding(.horizontal, 16)
        .padding(.bottom, 4)
    }
}

private struct StorageGlassCapsule: ViewModifier {
    func body(content: Content) -> some View {
        if #available(iOS 26.0, *) {
            content.glassEffect(.regular.interactive(), in: .capsule)
        } else {
            content.background(.ultraThinMaterial, in: Capsule())
        }
    }
}

// MARK: - Detail screens

struct StorageAppDetailView: View {
    let app: StorageApp
    @State private var confirmingDelete = false

    var body: some View {
        List {
            Section {
                HStack(alignment: .center, spacing: 16) {
                    StorageIcon(name: app.iconName, size: 70)
                    VStack(alignment: .leading, spacing: 2) {
                        Text(app.name)
                        if let version = app.version {
                            Text(version).font(.subheadline).foregroundStyle(.secondary)
                        }
                        if let developer = app.developer {
                            Text(developer).font(.subheadline).foregroundStyle(.secondary)
                        }
                    }
                    Spacer(minLength: 0)
                }
                .padding(.vertical, 6)

                LabeledContent("App Size", value: StorageFormat.size(app.resolvedAppSizeMB))
                LabeledContent("Documents & Data", value: StorageFormat.size(app.documentsMB))
            }

            Section {
                Button {} label: {
                    Text("Offload App").frame(maxWidth: .infinity)
                }
            } footer: {
                Text("This will free up storage used by the app, but keep its documents and data. Reinstalling the app will reinstate your data if the app is still available for download.")
            }

            Section {
                Button(role: .destructive) {
                    confirmingDelete = true
                } label: {
                    Text("Delete App").frame(maxWidth: .infinity)
                }
            } footer: {
                Text("This will delete the app and all related data from this iPhone. This action can’t be undone.")
            }
        }
        .listStyle(.insetGrouped)
        .navigationTitle(app.name)
        .navigationBarTitleDisplayMode(.inline)
        .dynamicTypeSize(.xLarge)
        .preferredColorScheme(.dark)
        // Demo only: nothing is ever deleted or offloaded.
        .confirmationDialog("Delete \(app.name)?", isPresented: $confirmingDelete, titleVisibility: .visible) {
            Button("Delete App", role: .destructive) {}
            Button("Cancel", role: .cancel) {}
        }
    }
}

struct StorageSystemDetailView: View {
    let title: String
    let sizeText: String
    let iconID: String

    var body: some View {
        List {
            Section {
                HStack(spacing: 16) {
                    StorageIcon(name: "StorageIcon_\(iconID)", size: 70)
                    Text(title)
                    Spacer(minLength: 0)
                }
                .padding(.vertical, 6)
                LabeledContent("Size", value: sizeText)
            }
        }
        .listStyle(.insetGrouped)
        .navigationTitle(title)
        .navigationBarTitleDisplayMode(.inline)
        .dynamicTypeSize(.xLarge)
        .preferredColorScheme(.dark)
    }
}

struct HiddenAppsView: View {
    var body: some View {
        List {
            Section {
                VStack(spacing: 10) {
                    Image(systemName: "square.stack.3d.up.slash")
                        .font(.system(size: 54))
                        .foregroundStyle(.secondary)
                        .padding(.top, 24)
                    Text("No Hidden Apps")
                        .font(.largeTitle.weight(.bold))
                        .multilineTextAlignment(.center)
                    Text("No hidden apps found.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .padding(.bottom, 24)
                }
                .frame(maxWidth: .infinity)
            }
        }
        .listStyle(.insetGrouped)
        .navigationTitle("Hidden Apps")
        .navigationBarTitleDisplayMode(.inline)
        .dynamicTypeSize(.xLarge)
        .preferredColorScheme(.dark)
    }
}

